 insert into private.ielts_learning_tasks(code,version,title,skill,purpose,instructions,success_description,taxonomy_version_id,pilot_student,questions,content,review_record,content_sha256,requires_review) values('bh-ielts-targeted-reading-r33-v2','0.2.0','Lesson 6 step 6 of 6: Mixed check','reading','independent_check','Read LEARN FIRST and the worked example. Then answer six new questions. Work on your own, without notes, a dictionary or help. Tell your teacher if anything interrupted you.','Use the whole routine: TYPE, LOCATE by meaning, PROVE with the exact words, REJECT the trap.','ad250533-8582-4bc5-986b-32b0c9640a16','b30e9c28-96f1-4d34-83e9-9b28b4926f42','[{"id": "q1", "prompt": "Which paragraph contains a reference to a group that is especially at risk from heat?", "accepted_answers": ["B"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q2", "prompt": "Which paragraph contains an explanation of why deeper planting is not always possible?", "accepted_answers": ["D"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "options": [{"value": "A", "label": "Paragraph A"}, {"value": "B", "label": "Paragraph B"}, {"value": "C", "label": "Paragraph C"}, {"value": "D", "label": "Paragraph D"}, {"value": "E", "label": "Paragraph E"}, {"value": "F", "label": "Paragraph F"}]}, {"id": "q3", "prompt": "Heat-absorbing materials such as asphalt release their stored energy only ________ after sunset.", "accepted_answers": ["gradually"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q4", "prompt": "Many older buildings could support deeper planting only after costly ________.", "accepted_answers": ["structural reinforcement"], "taxonomy_node_id": "be5b2be3-ffb1-4cfb-95c8-cb9e3e9101de", "supporting_node_id": "fc8a9d7e-3fe4-48a4-9325-84b193ee747c", "answer_format": "text"}, {"id": "q5", "prompt": "Which group says that planted roofs can protect the floors closest to them?", "accepted_answers": ["D"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}, {"id": "q6", "prompt": "Which group says that green roofs should not be treated as a complete answer on their own?", "accepted_answers": ["A"], "taxonomy_node_id": "3cc4beec-8c09-4289-bd3d-185f5319240a", "supporting_node_id": "fd1c70d0-1cde-4423-b18c-b2d9fa5842b3", "options": [{"value": "A", "label": "A  urban planners"}, {"value": "B", "label": "B  property owners"}, {"value": "C", "label": "C  ecologists"}, {"value": "D", "label": "D  engineers"}, {"value": "E", "label": "E  epidemiologists"}]}]'::jsonb,'{"scope": "Targeted IELTS preparation exercise; not a full paper.", "suggested_minutes": 10, "mapping_scope": "Task-specific reviewed focus with canonical English registry references. Not an IELTS/English equivalence or a pooled Academic Profile claim.", "focus_code": "bh-ielts-reading-targeted-focus-v1", "teacher_notes": "1 B: \"elderly residents of poorly ventilated top-floor apartments appear especially vulnerable\". Especially at risk = especially vulnerable. Trap D: pedestrians feel the heat but are not said to be at risk.\n2 D: deeper substrate \"is heavy when saturated\" and many older buildings \"could not bear the additional load\". Trap F: it offers cool roofs, an option, not the reason.\n3 gradually (paragraph A): \"surrender it only gradually once the sun has set\". Release = surrender; after sunset = once the sun has set. Trap: ''throughout the day'' is when the heat is absorbed.\n4 structural reinforcement (paragraph D): \"without expensive structural reinforcement\". Costly = expensive. Trap: ''additional load'' is the problem, not the fix.\n5 engineers: \"Engineers note that a planted roof ... may keep its upper floors comfortable\". The floors closest to the roof are the upper floors.\n6 urban planners: they \"regard green roofs as one element of a broader strategy rather than a remedy in themselves\". Not a complete answer = not a remedy in themselves.\nRead each explanation, then find the proof in the passage yourself.", "focus": "Matching information, sentence completion and matching features on one passage, with nearby distractors."}'::jsonb || jsonb_build_object('passage', to_jsonb('LEARN FIRST: use the whole routine on new questions

Six new questions on the same passage. Work on your own and use the four-step routine:
1. TYPE: what kind of information or word does the question need?
2. LOCATE: find it by MEANING, not by a word you recognise.
3. PROVE: point to the exact words in the passage.
4. REJECT: name the tempting wrong answer and why it is wrong.

WORKED EXAMPLE
"Which paragraph contains a reference to a cheaper alternative to green roofs?"
1. Type: an option (alternative), and it must be cheaper.
2. Locate: paragraph F, reflective cool roofs.
3. Prove: "are far cheaper on buildings whose structure cannot support soil".
4. Reject: E talks about costs ("costs substantially more"), but it offers no alternative. Echo word, wrong kind.
Answer: F

Questions 1-2: choose the paragraph, A-F. Questions 3-4: NO MORE THAN TWO WORDS from the passage. Questions 5-6: choose the group.' || '

